// One item per partner, so the Gmail node sends one mail each rather than one mail
// with everybody on it. Partners must not see who else was asked: it tells them who
// they are bidding against, and the desk loses the rate.
const burst = $input.first().json;
return burst.recipients.map((r) => ({
  json: {
    ref: burst.ref,
    to: r.email,
    partner: r.partner,
    subject: burst.mail.subject,
    body: burst.mail.body,
  },
}));
